import re

PATH = '/home/lane/MythosMini/slm_alliance.html'
src = open(PATH).read()

def rep(old, new, count=1):
    global src
    assert old in src, 'MISSING: ' + old[:70]
    src = src.replace(old, new, count)

# ── 1. Revert layout: drop grid wrappers, absolutely position logo ──
rep('''<section class="hero">
  <div class="hero-inner">
    <div class="hero-copy">
    <p class="hero-eyebrow">''', '''<section class="hero">
    <p class="hero-eyebrow">''')

rep('''    </div>
    </div>
    <div class="hero-logo">
''', '''    </div>
    <div class="hero-logo">
''')

rep('''    </div>
  </div>
</section>

''', '''    </div>
</section>

''', 1)

rep('''.hero-inner {
    display: grid;
    grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
    gap: 2.5rem;
    align-items: center;
}

.hero-logo {
    display: grid;
    place-items: center;
    opacity: 0;
    animation: rise 0.9s cubic-bezier(0.22, 1, 0.36, 1) 0.3s forwards;
}

@media (max-width: 820px) {
    .hero-inner { grid-template-columns: 1fr; }
    .hero-logo { order: -1; }
    .hero-logo .ai-drop-logo-202606 { --logo-size: min(50vmin, 240px); }
}''', '''.hero { position: relative; }

.hero-logo {
    position: absolute;
    right: 2rem;
    top: 50%;
    transform: translateY(-50%);
}

@media (max-width: 880px) {
    .hero-logo { display: none; }
}''')

# hero h1/lede keep their width caps so the logo sits in the free right space
rep('--logo-size:min(38vmin,340px);', '--logo-size:min(30vmin,320px);')

# ── 2. Remove the light sweep ("sparkle") ──
i = src.index('.ai-drop-logo-202606::after{')
e = src.index('}', src.index('animation:aiLogoSweep202606', i)) + 1
src = src[:i] + src[e:]
i = src.index('@keyframes aiLogoSweep202606')
e = src.index('}}', i) + 2
src = src[:i] + src[e:]

# ── 3. Wavy boil on the logo: turbulence displacement, discrete seed flips ──
rep('''  <svg xmlns="http://www.w3.org/2000/svg" width="2000" height="2000" viewBox="0 0 2000 2000" role="img" aria-label="Logo">
    <path fill="#FAFAF9" d="M0 0L2000 0L2000 2000L0 2000L0 0Z"/>''',
'''  <svg xmlns="http://www.w3.org/2000/svg" width="2000" height="2000" viewBox="0 0 2000 2000" role="img" aria-label="Logo">
    <defs>
      <filter id="logoBoil" x="-5%" y="-5%" width="110%" height="110%">
        <feTurbulence type="fractalNoise" baseFrequency="0.011" numOctaves="2" seed="1" result="noise">
          <animate attributeName="seed" values="1;7;13;4" dur="0.64s" repeatCount="indefinite" calcMode="discrete"/>
        </feTurbulence>
        <feDisplacementMap in="SourceGraphic" in2="noise" scale="22" xChannelSelector="R" yChannelSelector="G"/>
      </filter>
    </defs>
    <g filter="url(#logoBoil)">
    <path fill="#FAFAF9" d="M0 0L2000 0L2000 2000L0 2000L0 0Z"/>''')

rep('''C 45 65 5 55 5 34 C 5 13 46 7 100 5 Z" fill="none" stroke="#8fbcab"''',
    '''C 45 65 5 55 5 34 C 5 13 46 7 100 5 Z" fill="none" stroke="#8fbcab"''')  # sanity no-op for circle

# close the <g> before </svg> of the logo svg (the one containing logoBoil)
li = src.index('url(#logoBoil)')
le = src.index('</svg>', li)
src = src[:le] + '</g>\n  ' + src[le:]

open(PATH, 'w').write(src)
print('OK')
